Definition dof_exitE_stmt : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s5x s6x s7x s8x s9x t3 t4 t5 t6 : word)
    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj jl jh j24 : list byte)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (ecs : list cell) (g : bool)
    (h0 h1 h2 h3 : word) (shb : list byte),
  dof_ctx H LF m m1 sp spa gsz gj ra s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 ecs g lo shi ff fp h0 h1 h2 h3 shb ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> dof_core c c1 -> Z.of_nat (cells_size ecs) = 24 ->
  rw_cells bsegs m1 spa [CB 168 jl; C8 (wz E)] ->
  rw_cells bsegs m1 (spa + 176) [CB 24 j24] ->
  rw_cells bsegs m1 (spa + 200) [CB 16 jh] ->
  evt bsegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz (Z.shiftr ff 3 + 2147450880)) (wz ff) s5x s6x s7x s8x s9x (wz ff) (wz ASHADOW_BASE) t3 t4 t5 t6)
        F (Z_to_bv 64 0xd5d84) fc None m1 (seg_rom bsegs)).

